class EPCSim(Core):

    """
    Class needed for connection with EPCSim. Next it set paths and name of file cfg.

    :param addr: address url of host
    :param username: default value is 'ute'. It is the name of host
    :param password: default password is 'ute', needed for connection with the host
    :param dir_path: default '/opt/iphy/latest, it is path to epcsim binaries
    :param cfg_filename: name of config file for epcsim, default config.lua
    :param mme_ip: address ip of Mobility Management Entity (core network architecture)
    :param mcc: Mobile Country Code - unique code which identifying the country of given network
    :param mnc: Mobile Network Code -  unique number identifying the network. Used in combination with mcc.
    :param tac: Tracking Area Code - accepts 3 digital values
    """

    def __init__(self, addr, username='ute', password='ute', dir_path='/opt/iphy/latest',
                 cfg_filename='config.lua', mme_ip='10.1.1.100', mcc='311', mnc='489', tac='788'):
        super(EPCSim, self).__init__()

        self._set_attr('addr', addr)
        self._set_attr('username', username)
        self._set_attr('password', password)

        path = os.path.join(dir_path, cfg_filename)
        self._set_attr('cfg_path', path)
        self._set_attr('dir_path', dir_path)
        self._set_attr('cfg_filename', cfg_filename)

        self._set_attr('mme_ip', mme_ip)
        self._set_attr('mcc', mcc)
        self._set_attr('mnc', mnc)
        self._set_attr('tac', tac)


class Lteemu(Host):
    def __init__(self, addr, username='ute', password='ute',
                 dir_path='/opt/lteemu', cfg_filename='basic_cfg_LteEmu.cfg'):
        super(Lteemu, self).__init__(addr=addr, username=username, password=password)
        self._set_attr('dir_path', dir_path)
        self._set_attr('cfg_filename', cfg_filename)


